    letter-spacing:-0.01em;
    text-transform:uppercase;
  }
  .masthead .alt{
    margin-top:14px;
    font-size:.9rem;
    font-weight:600;
    letter-spacing:.05em;
  }
  .artist{
    background:var(--red);
    color:#fff;
    padding:30px 34px;
    display:flex;
    flex-direction:column;
    justify-content:center;
  }
  .artist .name{ font-size:1.5rem; font-weight:800; letter-spacing:.02em; }
  .artist .meta{
    margin-top:10px;
    font-size:.78rem;
    font-weight:600;
    text-transform:uppercase;
    letter-spacing:.16em;
    opacity:.92;
  }

  /* ---------- gallery: 3D reconstruction + story ---------- */
  .gallery{ display:grid; grid-template-columns:7fr 5fr; }
  .stage{ padding:30px; border-right:var(--w) solid var(--ink); }
