  .stage-inner canvas{ width:100%; height:100%; display:block; }
  .stage-note{
    position:absolute; inset:0;
    display:flex; align-items:center; justify-content:center;
    text-align:center; padding:24px;
    font-size:.95rem; font-weight:600;
  }
  .stage-caption{
    margin-top:16px;
    font-size:.78rem;
    font-weight:600;
    text-transform:uppercase;
    letter-spacing:.08em;
  }
  .side{ padding:30px; display:flex; flex-direction:column; gap:26px; }
  .eyebrow{
    margin:0 0 10px;
    font-size:.72rem;
    font-weight:800;
    letter-spacing:.2em;
    text-transform:uppercase;
  }
  .side p{ margin:0; }
  .block{ padding:22px 24px; }
  .block--blue{ background:var(--blue); color:#fff; }
  .block--ink{ background:var(--ink); color:#fff; }
  .block h3{ margin:0 0 8px; font-size:.95rem; font-weight:800; letter-spacing:.12em; text-transform:uppercase; }
  .block p{ margin:0; font-size:.95rem; }
  .chips{ display:flex; gap:8px; margin-top:14px; }
  .chip{ width:24px; height:24px; border:1px solid var(--ink); }
  .chip--red{ background:var(--red); }
  .chip--blue{ background:var(--blue); border-color:transparent; }
  .chip--yellow{ background:var(--yellow); }
  .chip--white{ background:#fff; }
  .chip--grey{ background:var(--grey); }
  .chip--black{ background:var(--ink); }

